export const envelope = [31, 24, 31];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];

  const DEEP = "minecraft:polished_deepslate";
  const BLACK = "minecraft:black_concrete";
  const GRAY = "minecraft:gray_concrete";
  const LIGHT = "minecraft:light_gray_concrete";
  const IRON = "minecraft:iron_block";
  const CYAN = "minecraft:cyan_concrete";
  const LAMP = "minecraft:sea_lantern";
  const BARS = "minecraft:iron_bars";
  const SMOOTH = "minecraft:smooth_stone";
  const ROOM_FLOOR = "minecraft:polished_andesite";
  const MOSSY = "minecraft:mossy_stone_bricks";
  const MOSS = "minecraft:moss_block";

  function put(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  function box(x0, x1, y0, y1, z0, z1, block) {
    for (let y = y0; y <= y1; y++) {
      for (let x = x0; x <= x1; x++) {
        for (let z = z0; z <= z1; z++) {
          put(x, y, z, block);
        }
      }
    }
  }

  const ground = new Array(W);
  for (let x = 0; x < W; x++) {
    ground[x] = new Array(D);
    for (let z = 0; z < D; z++) {
      const h = api.heightAt(x, z);
      ground[x][z] = Number.isFinite(h) ? h : 0;
    }
  }

  const xMin = 2;
  const xMax = 28;
  const zMin = 2;
  const zMax = 28;
  const seatCourse = 3;

  for (let x = xMin; x <= xMax; x++) {
    for (let z = zMin; z <= zMax; z++) {
      const h = ground[x][z];
      const first = Math.max(
        0,
        Math.min(seatCourse - 1, Math.ceil(seatCourse + h))
      );

      for (let y = first; y < seatCourse; y++) {
        const block = y === seatCourse - 1
          ? DEEP
          : (h < -1 ? DEEP : BLACK);
        put(x, y, z, block);
      }
    }
  }

  box(13, 17, 0, 0, 0, 0, SMOOTH);
  box(13, 17, 0, 1, 1, 1, SMOOTH);
  box(13, 17, 0, 2, 2, 2, SMOOTH);

  box(7, 10, 0, 2, 1, 2, DEEP);
  box(20, 23, 0, 2, 1, 2, DEEP);
  box(7, 10, 3, 4, 1, 2, BLACK);
  box(20, 23, 3, 4, 1, 2, BLACK);
  put(8, 3, 1, CYAN);
  put(22, 3, 1, CYAN);
  put(8, 4, 1, LAMP);
  put(22, 4, 1, LAMP);

  box(xMin, xMax, seatCourse, seatCourse, zMin, zMax, DEEP);
  box(14, 16, 3, 3, 4, 26, IRON);
  box(5, 12, 3, 3, 4, 14, ROOM_FLOOR);
  box(18, 25, 3, 3, 4, 14, ROOM_FLOOR);
  box(5, 12, 3, 3, 16, 26, ROOM_FLOOR);
  box(18, 25, 3, 3, 16, 26, ROOM_FLOOR);

  for (let y = 4; y <= 9; y++) {
    for (let x = xMin; x <= xMax; x++) {
      for (let z = zMin; z <= zMax; z++) {
        const boundary =
          x === xMin ||
          x === xMin + 1 ||
          x === xMax - 1 ||
          x === xMax ||
          z === zMin ||
          z === zMin + 1 ||
          z === zMax - 1 ||
          z === zMax;

        if (!boundary) {
          continue;
        }

        const opening =
          (z === zMin || z === zMin + 1) &&
          x >= 14 &&
          x <= 16 &&
          y <= 7;

        if (!opening) {
          const block = y === 4 || y === 9
            ? DEEP
            : (y === 8 ? LIGHT : BLACK);
          put(x, y, z, block);
        }
      }
    }
  }

  for (let y = 4; y <= 8; y++) {
    const wall = y === 4 ? DEEP : (y === 8 ? LIGHT : BLACK);

    for (let z = 4; z <= 26; z++) {
      put(4, y, z, wall);
      put(26, y, z, wall);

      const opening =
        (z === 9 || z === 10 || z === 20 || z === 21) &&
        y <= 7;

      if (!opening) {
        put(13, y, z, wall);
        put(17, y, z, wall);
      }
    }

    for (let x = 4; x <= 13; x++) {
      put(x, y, 15, wall);
    }
    for (let x = 17; x <= 26; x++) {
      put(x, y, 15, wall);
    }
  }

  const doorSouthLower =
    "minecraft:iron_door[facing=south,half=lower,hinge=left,open=true,powered=false]";
  const doorSouthUpper =
    "minecraft:iron_door[facing=south,half=upper,hinge=left,open=true,powered=false]";
  const doorEastLower =
    "minecraft:iron_door[facing=east,half=lower,hinge=left,open=true,powered=false]";
  const doorEastUpper =
    "minecraft:iron_door[facing=east,half=upper,hinge=left,open=true,powered=false]";
  const doorWestLower =
    "minecraft:iron_door[facing=west,half=lower,hinge=right,open=true,powered=false]";
  const doorWestUpper =
    "minecraft:iron_door[facing=west,half=upper,hinge=right,open=true,powered=false]";

  put(15, 4, 2, doorSouthLower);
  put(15, 5, 2, doorSouthUpper);

  const roomDoorZ = [9, 20];
  for (let i = 0; i < roomDoorZ.length; i++) {
    const z = roomDoorZ[i];
    put(13, 4, z, doorEastLower);
    put(13, 5, z, doorEastUpper);
    put(17, 4, z, doorWestLower);
    put(17, 5, z, doorWestUpper);
  }

  box(xMin, xMax, 9, 9, zMin, zMax, DEEP);
  box(xMin + 1, xMax - 1, 10, 10, zMin + 1, zMax - 1, BLACK);

  for (let x = 3; x <= 27; x++) {
    put(x, 11, 3, DEEP);
    put(x, 11, 27, DEEP);
  }
  for (let z = 4; z <= 26; z++) {
    put(3, 11, z, DEEP);
    put(27, 11, z, DEEP);
  }

  put(3, 12, 3, IRON);
  put(27, 12, 3, IRON);
  put(3, 12, 27, IRON);
  put(27, 12, 27, IRON);

  box(11, 19, 11, 11, 11, 19, DEEP);
  box(12, 18, 12, 13, 12, 18, BLACK);
  box(13, 17, 13, 13, 13, 17, IRON);

  for (let x = 13; x <= 17; x++) {
    put(x, 12, 12, CYAN);
    put(x, 12, 18, CYAN);
  }
  for (let z = 13; z <= 17; z++) {
    put(12, 12, z, CYAN);
    put(18, 12, z, CYAN);
  }

  const moduleLights = [
    [15, 12, 12],
    [15, 12, 18],
    [12, 12, 15],
    [18, 12, 15]
  ];
  for (let i = 0; i < moduleLights.length; i++) {
    const p = moduleLights[i];
    put(p[0], p[1], p[2], LAMP);
  }

  for (let x = 4; x <= 12; x++) {
    put(x, 6, 2, CYAN);
  }
  for (let x = 18; x <= 26; x++) {
    put(x, 6, 2, CYAN);
  }
  for (let x = 4; x <= 26; x++) {
    put(x, 6, 28, CYAN);
  }
  for (let z = 5; z <= 25; z++) {
    put(2, 6, z, CYAN);
    put(28, 6, z, CYAN);
  }

  const wallLights = [
    [6, 6, 2],
    [10, 6, 2],
    [20, 6, 2],
    [24, 6, 2],
    [2, 6, 8],
    [2, 6, 20],
    [28, 6, 8],
    [28, 6, 20],
    [8, 6, 28],
    [22, 6, 28]
  ];
  for (let i = 0; i < wallLights.length; i++) {
    const p = wallLights[i];
    put(p[0], p[1], p[2], LAMP);
  }

  for (let y = 5; y <= 7; y++) {
    put(13, y, 2, CYAN);
    put(17, y, 2, CYAN);
  }
  for (let x = 13; x <= 17; x++) {
    put(x, 8, 2, IRON);
    put(x, 8, 3, IRON);
  }

  for (let x = 5; x <= 25; x += 2) {
    put(x, 10, 4, CYAN);
    put(x, 10, 26, CYAN);
  }
  for (let z = 6; z <= 24; z += 2) {
    put(4, 10, z, CYAN);
    put(26, 10, z, CYAN);
  }

  const roofLights = [
    [7, 10, 4],
    [23, 10, 4],
    [7, 10, 26],
    [23, 10, 26],
    [4, 10, 8],
    [4, 10, 22],
    [26, 10, 8],
    [26, 10, 22]
  ];
  for (let i = 0; i < roofLights.length; i++) {
    const p = roofLights[i];
    put(p[0], p[1], p[2], LAMP);
  }

  const mossPatches = [
    [4, 4, 2],
    [5, 4, 2],
    [6, 4, 2],
    [24, 4, 2],
    [25, 4, 2],
    [26, 4, 2],
    [2, 4, 7],
    [2, 4, 8],
    [2, 4, 9],
    [28, 4, 18],
    [28, 4, 19],
    [28, 4, 20],
    [3, 5, 27],
    [4, 5, 27],
    [5, 5, 27]
  ];
  for (let i = 0; i < mossPatches.length; i++) {
    const p = mossPatches[i];
    put(p[0], p[1], p[2], MOSSY);
  }

  const roofMoss = [
    [4, 11, 3],
    [26, 11, 27],
    [3, 11, 24],
    [27, 11, 6]
  ];
  for (let i = 0; i < roofMoss.length; i++) {
    const p = roofMoss[i];
    put(p[0], p[1], p[2], MOSS);
  }

  function addMast(x, z, top, alongX) {
    put(x, 11, z, IRON);
    put(x, 12, z, LAMP);

    for (let y = 13; y < top; y++) {
      put(x, y, z, BARS);
    }
    put(x, top, z, CYAN);

    if (alongX) {
      for (let d = -2; d <= 2; d++) {
        put(x + d, 16, z, BARS);
      }
    } else {
      for (let d = -2; d <= 2; d++) {
        put(x, 16, z + d, BARS);
      }
    }
  }

  addMast(7, 7, 20, true);
  addMast(23, 7, 20, false);
  addMast(23, 23, 20, true);

  put(15, 14, 15, IRON);
  for (let y = 15; y < 23; y++) {
    put(15, y, 15, BARS);
  }
  put(15, 23, 15, CYAN);

  for (let x = 11; x <= 19; x++) {
    put(x, 17, 15, BARS);
  }
  for (let z = 11; z <= 19; z++) {
    put(15, 20, z, BARS);
  }

  return {
    name: "High-Tech Apocalyptic Hideout",
    seatY: 3,
    anchors: {
      door: [15, 4, 2]
    },
    interiors: [
      {
        min: [5, 4, 4],
        max: [12, 8, 14],
        kind: "control"
      },
      {
        min: [18, 4, 4],
        max: [25, 8, 14],
        kind: "quarters"
      },
      {
        min: [5, 4, 16],
        max: [12, 8, 26],
        kind: "power"
      },
      {
        min: [18, 4, 16],
        max: [25, 8, 26],
        kind: "stores"
      },
      {
        min: [14, 4, 4],
        max: [16, 8, 26],
        kind: "hall"
      }
    ]
  };
}
